return ['logo' => 'assets/pahsb/media/f5b358b6-logo-puncak-alam.png','hero' => 'assets/pahsb/media/5321ccf9-puncak_alam_slide_b.jpg','heroAlt' => 'assets/pahsb/media/d2767b09-puncak_alam_slide_c.jpg','aboutImage' => 'assets/pahsb/media/8e83c79a-pahsb-overview-pano.jpg','townshipImage' => 'assets/pahsb/media/f283245e-bandar-puncak-alam-residentials.jpg','pages' => ['overview' => [['type' => 'h1','text' => 'Overview'],['type' => 'p','text' => 'Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. Puncak Alam is planned as an integrated self-contained township planned on total area of 14,000 acres in the district of Kuala Selangor, Selangor Darul Ehsan. PAHSB holds the development right in respects of over 3,600 acres.'],['type' => 'p','text' => 'With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units. Apart from residential and commercial units, various public facilities and amenities were also made available for the community such as 3 primary schools, 2 secondary schools, police base station, sport complex, supermarket and drive-thru fast food restaurant. The new UiTM campus known as UiTM Puncak Alam is also situated in the township with student capacity of 30,000 and will be facilitated with 17 faculties.'],['type' => 'p','text' => 'The company’s vision is to provide a wide range of products to cater for different needs of customers and to provide condusive social, recreational, religious, commercial and educational facilities directly and indirectly to the community.'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'board-of-directors' => [['type' => 'h1','text' => 'Board of Directors'],['type' => 'h3','text' => 'Pn Nur Dayana Tan Sri Rozali'],['type' => 'p','text' => 'Director, Puncak Alam Housing Sdn Bhd'],['type' => 'p','text' => 'Pn Nur Dayana graduated from Murdoch University, Perth, Western Australia. She holds a Bachelor of Arts Degree in Communication in Media Studies & Women Studies.'],['type' => 'p','text' => 'She holds directorship of few companies namely FAROZ Boutique, Puncak Hotel Phnom Penh Cambodia and Puncak Alam Housing Sdn Bhd. She is also a Vice President of Persatuan Kucing Malaysia (Malaysia Cat Society) and member of Islamic Fashion Festival (IFF).'],['type' => 'h3','text' => 'Pn Farziyah Mohd Fadzil'],['type' => 'p','text' => 'Chief Executive Officer, Puncak Alam Housing Sdn Bhd'],['type' => 'p','text' => 'Pn Farziyah holds a Bachelor of Science Degree in Business Administration which specialized in Management and Organizational Behaviour from University of Missouri at St. Louise, USA (1986 – 1991).'],['type' => 'p','text' => 'Prior to joining Puncak Alam Housing Sdn Bhd, she worked with SAP Holding Berhad as Manager in the Property Division. She was then joined Puncak Alam Housing Sdn Bhd in August 1988. In 2005, she was promoted as Director of Property Maintenance arm of the Company and in 2008 she was then given a responsibility to lead the Company operation as Chief Executive Officer.'],['type' => 'h3','text' => 'En Azlan Shah Tan Sri Rozali'],['type' => 'p','text' => 'Executive Director, Puncak Alam Housing Sdn Bhd'],['type' => 'p','text' => 'En Azlan Shah Tan Sri Rozali graduated with a Bachelor of Arts Degree in Business and Marketing from the Middlesex University, Hendon Business Campus, London, United Kingdom.'],['type' => 'p','text' => 'In 2010, he joined SYABAS as an Executive and had exposures and experiences in the area of Human Resources & Administration, Finance & Accounts and SYABAS district offices. Encik Azlan Shah is an EXCO Member of the Youth Chamber in the Malay Chamber of Commerce for the State of Selangor, Co-Founder and Vice President of 1Malaysia Youth Entrepreneurs Club. In 2011, he received the title of ‘Leftenan Rejimen Pakar Pengendalian Air Ke – 60 RAJD (Askar Wataniah)’.'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'vision-mission' => [['type' => 'h1','text' => 'Vision & Mission'],['type' => 'h3','text' => 'Our Vision & Mission'],['type' => 'p','text' => 'To provide a wide range of products to cater for different needs of customers and to provide conducive social, recreational, religious, commercial and educational facilities directly and indirectly to the community.'],['type' => 'h3','text' => 'Our Core Values'],['type' => 'p','text' => 'Commitment – Committing to great product, service, and other initiatives that impact lives within and outside the organization.'],['type' => 'p','text' => 'Community – Contributing to society and demonstrating corporate social responsibility.'],['type' => 'p','text' => 'Integrity – Acting with honesty and honour without compromising the truth.'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'puncak-alam-township' => [['type' => 'h1','text' => 'Puncak Alam Township'],['type' => 'p','text' => 'Puncak Alam township is within the District of Kuala Selangor, bordering the District of Petaling Jaya and Shah Alam township. The township is strategically located to the North West of the Klang Valley between Petaling Jaya and Shah Alam and it is easily accessible to all major conurbations of the Klang Valley. The township currently house about 50,000 populations.'],['type' => 'p','text' => 'Fast Facts About Puncak Alam Township'],['type' => 'li','text' => 'Puncak Alam township covers approximately 14,000 acres of land area, having commenced in early 1997.'],['type' => 'li','text' => 'Total acreage developed by Puncak Alam Housing Sdn Bhd to date : 3,114 acres'],['type' => 'li','text' => 'The township is designed to be an integrated modern city incorporating the state-of-the-art technology that cares for its community with comprehensive facilities and amenities.'],['type' => 'li','text' => 'The development of the township is meant for a population of 500,000 residents in the new growth corridor in Selangor.'],['type' => 'li','text' => 'Situated on the west of Kuala Lumpur, north of Shah Alam and within the growth corridor of major cities such as Kuala Lumpur and Petaling Jaya.'],['type' => 'li','text' => 'The town location is very unique as it is the only new city that is located not just by the side of one prominent city but four; Klang, Shah Alam, Petaling Jaya and Kuala Lumpur.'],['type' => 'li','text' => 'From any of the four cities, Puncak Alam township is located only 15km to Klang, 20km to Shah Alam, 25km to Petaling Jaya and 30km to Kuala Lumpur.'],['type' => 'li','text' => 'Puncak Alam township central location also provides close proximity to KLIA and Putrajaya as well as Cyberjaya via Kesas Highway.'],['type' => 'li','text' => 'UiTM Puncak Alam is only a few kilometers away from Puncak Alam residential area.'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'projects' => [['type' => 'h1','text' => 'Projects'],['type' => 'li','text' => 'Completed'],['type' => 'h2','text' => 'Completed'],['type' => 'li','text' => 'Current'],['type' => 'h2','text' => 'Current'],['type' => 'p','text' => 'Bandar Puncak Alam Seksyen 2 was developed to accommodate 766 units of single, double storey terrace house and bungalows.'],['type' => 'h3','text' => 'Bandar Puncak Alam Seksyen 2'],['type' => 'p','text' => 'Bandar Puncak Alam Seksyen 7 & 8 covering 415 acres of land was developed to accommodate 1853 units of double storey terrace, semi-D, cluster house …'],['type' => 'h3','text' => 'Bandar Puncak Alam Seksyen 7 & 8'],['type' => 'p','text' => 'Bandar Puncak Alam Seksyen 12 & 13 was developed to accommodate 6,000 units of double storey terrace house, apartment, condominium and commercial shops.'],['type' => 'h3','text' => 'Bandar Puncak Alam Seksyen 12 & 13'],['type' => 'p','text' => 'UiTM Puncak Alam officially began operations on 1st June 2009. With an area of ​​1,085.75 acre, this campus is designed to accommodate an additional 20,000 …'],['type' => 'h3','text' => 'UiTM Puncak Alam'],['type' => 'p','text' => 'As a developing education town for Selangor, Puncak Alam had several public schools to cater the needs of residents and communities such as Sekolah Kebangsaan …'],['type' => 'h3','text' => 'Public Schools'],['type' => 'p','text' => 'Located nearby UiTM Puncak Alam Campus, it might be further out of the city centre, but you will like the traveling as you will be …'],['type' => 'h3','text' => 'Golf Driving Range & Cafe'],['type' => 'p','text' => 'Bandar Puncak Alam offers great access to a complete range of township facilities such as hypermarkets and shopping centres like Tesco and Econsave, medical centres …'],['type' => 'h3','text' => 'Other Facilities'],['type' => 'p','text' => 'Located in Seksyen 13 bandar Puncak Alam, this commercial hub comprises 73 units of double storey shop office and hawker center.'],['type' => 'h3','text' => 'Commercial Center'],['type' => 'p','text' => 'Pemaju kompleks masjid ini adalah Puncak Alam Housing Sdn Bhd manakala arkiyeknya ialah Design Rekabina Sdn Bhd dan juruhias dalaman adalah Al-Ciptra Design Associates Sdn …'],['type' => 'h3','text' => 'Masjid Puncak Alam'],['type' => 'p','text' => 'Surau Ar Rahimah located in Seksyen 2 Bandar Puncak Alam.'],['type' => 'h3','text' => 'Surau Ar Rahimah'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'news' => [['type' => 'h1','text' => 'News'],['type' => 'h2','text' => 'New Puncak Alam Mosque Completed'],['type' => 'p','text' => 'Pemaju kompleks masjid ini adalah Puncak Alam Housing Sdn Bhd manakala arkiyeknya ialah Design Rekabina Sdn Bhd dan juruhias dalaman adalah Al-Ciptra Design Associates Sdn …'],['type' => 'h2','text' => 'Newly Opened Tesco In Puncak Alam'],['type' => 'p','text' => 'Tesco Puncak Alam opens its doors on 28th November 2013 and hundreds of people made their way to the new complex since 8am! The opening …'],['type' => 'li','text' => 'About PAHSB Puncak Alam Housing Sdn Bhd (PAHSB) is a prime developer of a new township known as Puncak Alam. With exactly 15 years of experience in property development industry, PAHSB has successfully developed 3,114 acres of land and has sold over 7,458 commercial and residential units.']],'enquiry' => [['type' => 'h1','text' => 'Enquiry'],['type' => 'p','text' => 'Please fill in all the information and our customer service department will contact you back as soon as possible. Thank you.'],['type' => 'h3','text' => 'Contact Information'],['type' => 'p','text' => 'Company : Puncak Alam Housing Sdn Bhd (263280-A) Address : Bandar Puncak Alam, 42300 Puncak Alam, Selangor Darul Ehsan. Telephone No : +603 3393 1985 or +603 3393 4227 Fax No : +603 3392 8276'],['typ